mapper.update:
UPDATE app_user
SET last_login_ip = #{lastLoginIp},
    last_login_time = #{lastLoginTime}
WHERE id = #{id}

mapper.select:
SELECT 
FROM app_user

    is_deleted = 0

        AND nickname LIKE CONCAT('%', #{nickname}, '%')


        AND phone LIKE CONCAT('%', #{phone}, '%')


        AND status = #{status}


        AND create_time >= #{beginTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC

mapper.update:
UPDATE app_user
SET is_deleted = 1
WHERE id = #{id}

mapper.select:
SELECT 
FROM app_user u
LEFT JOIN app_user inv ON u.inviter_id = inv.id AND inv.is_deleted = 0


        AND u.nickname LIKE CONCAT('%', #{nickname}, '%')


        AND u.phone LIKE CONCAT('%', #{phone}, '%')


        AND u.status = #{status}


        AND u.vip_status = #{vipStatus}


        AND u.create_time >= #{beginTime}


        AND u.create_time <= #{endTime}


ORDER BY u.create_time DESC

mapper.update:
UPDATE app_user
SET vip_status = #{vipStatus}, vip_end_time = #{vipEndTime}
WHERE id = #{id}
